const artalePatchReport = { applied: [], added: [], removed: [], notes: [] };
// 原站資料的錯誤：職業本來沒有、卻被列在技能樹的技能（依使用者回報逐一加入）
const artaleExtraRemovals = {
    '黑騎士 (DarkKnight)': ['究極神盾']
};
(function applyArtalePatch() {
    if (new URLSearchParams(location.search).get('legacy') === '1') { artalePatchReport.notes.push('legacy=1：未套用魔改（顯示舊版）'); return; }
    const TIER_LEVEL = { 1: 10, 2: 30, 3: 70, 4: 120 };
    // 官網名稱 → 原站資料裡的舊名稱（官網沒標「名稱變更」，但原站資料用的是舊名）
    const ALIAS = { '電閃雷鳴': '雷閃電鳴', '專注弱點': '黑暗狙擊' };
    const clean = (n) => (ALIAS[n] || n);
    for (let [jobName, list] of Object.entries(artalePatchSpec)) {
        const job = allProfessionsData[jobName];
        if (!job) { artalePatchReport.notes.push('找不到職業 ' + jobName); continue; }
        // --- 刪除：魔改版移除的技能 + 原站資料的錯誤（職業本來就沒有的技能） ---
        const removeNames = list.filter(sp => sp.deleted).map(sp => sp.newName).concat(artaleExtraRemovals[jobName] || []);
        const removedIds = [];
        for (const [stage, arr] of Object.entries(job.skills)) {
            job.skills[stage] = arr.filter(s => {
                if (removeNames.includes(s.name)) { removedIds.push(s.id); artalePatchReport.removed.push(jobName + ' / ' + s.name + '（' + stage + '）'); return false; }
                return true;
            });
        }
        for (const arr of Object.values(job.skills)) for (const s of arr) for (const rid of removedIds) {
            if (s.preRequisite && s.preRequisite[rid] !== undefined) { delete s.preRequisite[rid]; artalePatchReport.notes.push(jobName + ' / ' + s.name + ' 的前置「' + rid + '」已隨技能刪除而移除'); }
        }
        list = list.filter(sp => !sp.deleted);
        const findAll = (name) => {
            const hits = [];
            for (const [stage, arr] of Object.entries(job.skills)) for (const s of arr) if (s.name === clean(name)) hits.push({ s, stage });
            return hits;
        };
        const byName = (name) => { const h = findAll(name); return h.length ? h[0].s : null; };
        for (const sp of list) {
            let hits = [];
            for (const n of sp.names) hits = hits.concat(findAll(n));
            if (hits.length === 0) {
                // 資料裡沒有這個技能 → 依轉職階段新增
                const stageName = job.jobStagesOrder[sp.tier];
                if (!stageName || !job.skills[stageName]) { artalePatchReport.notes.push(jobName + ' 無法新增 ' + sp.newName); continue; }
                const ns = { id: 'patch_' + sp.pid, name: sp.newName, maxLevel: sp.maxLevel || 1, requiredLevel: TIER_LEVEL[sp.tier], preRequisite: {}, description: sp.desc, imageUrl: (window.__IMG && window.__IMG['images/patch_' + sp.pid + '.png']) || ('images/patch_' + sp.pid + '.png'), levels: [null], _fromPatch: true };
                for (let i = 1; i <= ns.maxLevel; i++) ns.levels.push({ effect: '', fullDescription: sp.desc });
                job.skills[stageName].push(ns);
                hits = [{ s: ns, stage: stageName }];
                artalePatchReport.added.push(jobName + ' / ' + sp.newName + '（' + stageName + '）');
            }
            for (const { s } of hits) {
                const oldName = s.name;
                s._old = { name: s.name, maxLevel: s.maxLevel, description: s.description, preRequisite: JSON.stringify(s.preRequisite || {}), effects: s.levels.map(l => l ? l.effect : null) };
                s.name = sp.newName.length && hits.length === 1 ? sp.newName : s.name;
                if (sp.desc) s.description = sp.desc;
                if (sp.maxLevel && sp.maxLevel !== s.maxLevel) {
                    artalePatchReport.notes.push(jobName + ' / ' + s.name + ' 最高等級 ' + s.maxLevel + ' → ' + sp.maxLevel);
                    const old = s.levels;
                    s.maxLevel = sp.maxLevel;
                    s.levels = [null];
                    for (let i = 1; i <= sp.maxLevel; i++) s.levels.push(old[i] || { effect: '', fullDescription: s.description || '' });
                }
                if (sp.pre) {
                    const pid = byName(sp.pre[0]);
                    if (pid && pid !== s) s.preRequisite = { [pid.id]: sp.pre[1] };
                    else artalePatchReport.notes.push(jobName + ' / ' + s.name + ' 前置技能「' + sp.pre[0] + '」在資料中找不到，未更新前置');
                }
                // 逐級數值（附加在原效果後面，標示魔改）
                for (let i = 1; i <= s.maxLevel; i++) {
                    const lv = s.levels[i]; if (!lv) continue;
                    const parts = [];
                    for (const panel of sp.levelStats) {
                        const idx = i - panel.from_;
                        for (const st of panel.stats) if (st.after[idx] !== undefined && !['無', '刪除', '-'].includes(String(st.after[idx]))) parts.push(st.label + ': ' + st.after[idx] + ((st.unit && !String(st.after[idx]).endsWith(st.unit)) ? st.unit : ''));
                    }
                    if (parts.length) {
                        // 取代：舊效果中與魔改項目同類的片段刪掉，其餘（如消耗MP）保留，再接上魔改新數值
                        const labels = sp.levelStats.flatMap(pn => pn.stats.map(st => st.label));
                        const KEYS = ['攻擊力', '攻擊', '魔力', '防禦', '傷害', '持續', '冷卻', '次數', '目標', '倍率', '鬥氣', '機率', '速度', '恢復', '命中', '迴避', '暴擊', '減少', '降低', '增加', '提升', '時間', '範圍', '數量', '經驗', '消耗'];
                        const dmgLabel = labels.some(l => /倍率|傷害/.test(l));
                        const related = (k) => (dmgLabel && /攻擊力|威力|傷害/.test(k)) || labels.some(l => l === k || k.includes(l) || l.includes(k) || KEYS.some(w => k.includes(w) && l.includes(w) && w !== '消耗' && w !== '增加' && w !== '提升'));
                        const keep = (lv.effect || '').split(/，|, ?/).map(x => x.trim()).filter(Boolean).filter(seg => { const k = seg.split(/[:：]/)[0].trim(); return !related(k); });
                        lv.effect = keep.concat(parts).join('，');
                        lv.fullDescription = (s.description || '').split('\n')[0] + ' 等級' + i + '效果：' + lv.effect + '。';
                        lv.patched = true;
                    }
                }
                if (sp.otherPanels.length) {
                    // 其他數值表（依 INT、鬥氣量…）不寫進說明（太長），完整數值放進「顯示全部」的折線圖
                    s.extraCharts = sp.otherPanels.map(p => ({ title: p.title, axis: p.axis, from: p.from_, stats: p.stats.map(st => ({ label: st.label, after: st.after })) }));
                }
                s._patchNote = sp.summary; s._patchChanges = sp.changes;
                artalePatchReport.applied.push(jobName + ' / ' + oldName + (oldName !== s.name ? ' → ' + s.name : ''));
            }
        }
    }
})();

// 推薦配點：原站的配點是舊版數值，先全部清空（之後可自己新增）
for (const k of Object.keys(recommendedBuilds)) recommendedBuilds[k] = [];

// 原站資料的前置技能錯誤：前置指到不存在的技能 ID，導致永遠無法滿足（依使用者回報／檢查逐一修正）
(function fixDanglingPrerequisites() {
    const FIX = {
        '聖騎士 (Paladin)': { '屬性強化': { elementalStrike: 'elementalCharge' } },   // 前置應為「屬性攻擊」
        '箭神 (Bowmaster)': { '無形之箭': { crossbowBooster: 'bowBooster' } }          // 箭神應為「快速之箭」，不是弩的快速之弩
    };
    for (const [jobName, bySkill] of Object.entries(FIX)) {
        const job = allProfessionsData[jobName]; if (!job) continue;
        for (const arr of Object.values(job.skills)) for (const s of arr) {
            const map = bySkill[s.name]; if (!map || !s.preRequisite) continue;
            for (const [oldId, newId] of Object.entries(map)) {
                if (s.preRequisite[oldId] !== undefined) { s.preRequisite[newId] = s.preRequisite[oldId]; delete s.preRequisite[oldId]; }
            }
        }
    }
    // 檢查：還有沒有指到不存在技能的前置
    for (const [jobName, job] of Object.entries(allProfessionsData)) {
        const ids = new Set(Object.values(job.skills).flat().map(s => s.id));
        for (const arr of Object.values(job.skills)) for (const s of arr) for (const k of Object.keys(s.preRequisite || {})) {
            if (!ids.has(k)) artalePatchReport.notes.push('前置指到不存在的技能：' + jobName + ' / ' + s.name + ' → ' + k);
        }
    }
})();

// 冒險家頭像：改用官方職業頭像（emblems/*_face.webp），首頁職業卡會讀 cardImage
(function setExplorerPortraits() {
    const FACE = { '主教': 'bishop', '火毒大魔導': 'archmage-fp', '冰雷大魔導': 'archmage-il', '英雄': 'hero', '聖騎士': 'paladin', '黑騎士': 'darkknight',
        '箭神': 'bowmaster', '神射手': 'marksman', '暗影神偷': 'shadower', '夜使者': 'nightlord', '拳霸': 'viper', '槍神': 'captain' };
    for (const [jobName, job] of Object.entries(allProfessionsData)) {
        const zh = jobName.split(' ')[0];
        if (FACE[zh]) job.cardImage = 'emblems/' + FACE[zh] + '_face.webp';
    }
})();

